 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and not seen[ny][nx]:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            # Each object is a filled stack of concentric rectangular color bands.
            layers = {}
            for y, x in cells:
                depth = min(y-r0, r1-y, x-c0, c1-x)
                layers.setdefault(depth, set()).add(grid[y][x])
            max_depth = max(layers)
            band_colors = {d: next(iter(colors)) for d, colors in layers.items()}
            for y, x in cells:
                depth = min(y-r0, r1-y, x-c0, c1-x)
                out[y][x] = band_colors[max_depth-depth]
    return out
